TP.register({id:"lp7-g2",lp:7,grade:"2",mode:"curriculum",checks:6,nextGrade:"3rd grade",build(E){const F=E.F;const LAST_ROW="Tess was the only one still working when the light started to go. Every other row on the hill had been weeded and watered hours before. Hers was the long row at the bottom. Nobody wanted that row. The hose would not stretch that far. Every bucket had to be carried by hand. She was halfway down it when she heard the gate swing. Six people came through, each one swinging an empty bucket. Nobody said much. They spread out along the row. They worked from both ends toward the middle. The whole row was finished before the dark came down.";const HEDGE="A crow and a badger lived on two sides of the same hedge. All summer the crow found shiny bits of foil and wire. She dropped them over onto the badger's side. Badgers like to line their burrows with them. All summer the badger dug up fat beetles. He pushed the fattest ones through the hedge to the crow's side. Crows like beetles. Neither of them ever said thank you. Neither of them ever counted. The cold came. The badger's burrow was the warmest on the hill. The crow had eaten well too. She had enough to last the whole winter.";const TOOL_LIBRARY="A tool library works like a book library, except for one thing. The shelves hold drills and ladders and wheelbarrows. You join for a small fee. Sometimes it costs nothing at all. Then you may borrow what you need for a week. The idea makes sense because most tools sit still almost all of the time. A ladder in a garage gets used twice a year. It costs the same as a ladder that gets used every day. One shared ladder can do the work of thirty. Volunteers at the counter teach people too. They show how to use the tools safely. That is often the harder part of the job.";const GUIDE_DOG="A guide dog starts learning when it is still a puppy, but not with the person it will one day lead. For its first year it lives with a volunteer family, and that family has one job: make the puppy calm and friendly everywhere. Car rides. Crowds. Lifts. Loud streets. Then the dog goes back to the school for about five months of real training. The last part is the surprising one. A guide dog is taught to disobey. If the person says forward and a car is coming, the dog has to stand still and refuse. Trainers call that intelligent disobedience, and it is the hardest thing the dog ever learns.";const WORDS=["shared","kindly","thorn","sprout","reach","wrote","greenhouse","unpack","enough","should","plean","drorn"];const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const passage=(title,text)=>`<h3 style="margin:14px 0 4px;color:var(--sea)">${title}</h3><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${text}</p>`;const pills=(...w)=>`<div class="row center" style="margin-top:18px;gap:18px">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>{const eye=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`;const blush=(x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`;const smile=(x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`;return eye(cx-sp,cy)+eye(cx+sp,cy)+blush(cx-sp-7,cy+9)+blush(cx+sp+7,cy+9)+smile(cx,cy+9,mw||4)});const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",PINK="#F4899E",ROSE="#F6B3D0",PURPLE="#C9A6EC",PEACH="#F7C07A",CORALH="#EE8E86",BRASS="#D9A066",SKY="#FBD9E4";function heartShape(x,y,s,c){const k=s/60,c0=c||PINK;return`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})"><path d="M0 20 C-25 3 -30 -13 -18 -21 C-9 -27 -2 -22 0 -16 C2 -22 9 -27 18 -21 C30 -13 25 3 0 20 Z" fill="${c0}" stroke="${INK}" stroke-width="2.6" stroke-linejoin="round"/>`+at(0,-5,.5,K_FACE(0,0,12,4))+`</g>`}const heartSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*.85)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a paper heart">${heartShape(w/2,w*.51,w*.92,c)}</svg>`;function heartRow(n){const w=620,h=150,x0=40,x1=w-40,sag=22,ry=x=>{const t=(x-x0)/(x1-x0);return 44+4*sag*t*(1-t)};let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;b+=`<path d="M${x0} 44 Q${(x0+x1)/2} ${44+2*sag} ${x1} 44" fill="none" stroke="${BRASS}" stroke-width="5" stroke-linecap="round"/>`;const cols=[PINK,ROSE,PURPLE,PEACH,CORALH];for(let i=0;i<n;i++){const x=x0+(i+.5)*(x1-x0)/n;b+=heartShape(x,ry(x)+34,48,cols[i%5])}return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A string across the garden gate with ${n} paper hearts hanging from it">${b}</svg>`}function trayFig(rows,cols,tagText){const cell=72,w=cols*cell+40,h=rows*cell+58;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="20" fill="#E8D3BB" stroke="${INK}" stroke-width="4"/>`;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const x=20+c*cell,y=18+r*cell;b+=`<rect x="${x}" y="${y}" width="${cell-8}" height="${cell-8}" rx="12" fill="#FBF1E4" stroke="${INK}" stroke-width="2.6"/>`;b+=F.picXY(x+(cell-8)/2,y+(cell-8)/2,"sprout",44)||""}b+=`<text x="${w/2}" y="${h-16}" font-size="24" font-family="Andika,sans-serif" font-weight="700" text-anchor="middle" fill="#4A332A">${tagText}</text>`;return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,470)}" role="img" aria-label="A seedling tray with ${rows} rows of ${cols} little plants">${b}</svg>`}const CLOCKS=[["A",6,10],["B",4,35],["C",1,50],["D",9,25]];function clockRow(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;justify-content:center">`+CLOCKS.map(c=>`<div>${F.clock(c[1],c[2],200)}<p class="fig-label">Clock ${c[0]}</p></div>`).join("")+`</div>`}const LOG=F.table(["Day","Buckets carried","Who came"],[["Monday","12","4 people"],["Tuesday","20","7 people"],["Wednesday","8","3 people"],["Thursday","16","6 people"]],{caption:"Bucket Log"});function bedsFig(){const one=(pts,n)=>`<div>${F.poly(pts,{size:170,fill:"var(--sea-soft)",alt:"a garden bed shape"})}<p class="fig-label">Bed ${n}</p></div>`;return`<div class="figure" style="gap:14px;flex-wrap:wrap;justify-content:center;align-items:flex-end">`+one([[50,6],[94,92],[6,92]],1)+one([[22,14],[80,14],[96,92],[4,92]],2)+one([[50,4],[96,38],[78,94],[22,94],[4,38]],3)+one([[28,6],[72,6],[96,50],[72,94],[28,94],[4,50]],4)+`<div>${F.prism(1,1,1,{unit:84})}<p class="fig-label">Box 5</p></div></div>`}function pairFig(){const w=800,h=200,cell=56,x0=40,x1=480;const grp=(x,n)=>{let s="";const top=Math.ceil(n/2);for(let i=0;i<n;i++){const c=i<top?i:i-top,r=i<top?0:1;s+=heartShape(x+c*cell+cell/2,56+r*60,46,r?PURPLE:PINK)}return s};let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=grp(x0,14)+grp(x1,9);b+=`<text x="${x0+196}" y="178" font-size="26" font-family="Andika,sans-serif" font-weight="700" text-anchor="middle" fill="var(--muted)">Group A</text>`;b+=`<text x="${x1+140}" y="178" font-size="26" font-family="Andika,sans-serif" font-weight="700" text-anchor="middle" fill="var(--muted)">Group B</text>`;return`<svg viewBox="0 0 ${w} ${h}" width="740" role="img" aria-label="Group A has 14 paper hearts stacked in two rows of 7, so every heart has a partner under it. Group B has 9 paper hearts, 5 on top and 4 underneath, so the last heart on top has no partner.">${b}</svg>`}const STOPS=[{id:1,title:"Garden Word Flip",short:"Word Flip",parts:[{std:["RF.2.3"],kind:"words",words:WORDS,n:12,dur:95,dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading words with digraphs, blends, vowel teams, r-controlled vowels, a prefix, suffixes, silent letters, and irregular spellings",key:["Read each word in order. plean and drorn are made-up words: listen for the ea team saying long e, and for the or sound.","Watch for: the -ed ending said as /d/ on a final-e base (shared), the suffix -ly (kindly), th plus r-controlled or (thorn), a three-letter blend plus the ou diphthong (sprout), the ea team plus ch (reach), silent w plus final e (wrote), a compound word with two vowel teams (greenhouse), the prefix un- (unpack), the irregular ough said as /uf/ (enough), the irregular ould (should)."]}]},{id:2,title:"Trays in the Greenhouse",short:"Trays",parts:[{std:["2.OA.C.4"],n:5,dur:110,dir:"Look at the three trays. Answer out loud. Write the addition sentences on your paper.",desc:"finding the total in a rectangular array and writing it as a sum of equal addends",html:()=>`<p class="big" style="margin-top:0">The club starts its seeds in trays. Every little pot holds one plant.</p>`,fig:()=>`<div class="figure" style="gap:18px;flex-wrap:wrap;justify-content:center">${trayFig(4,3,"Tray 1")}${trayFig(5,5,"Tray 2")}${trayFig(3,4,"Tray 3")}</div>`,qs:["Look at Tray 1. How many rows are there, and how many plants are in each row? How many plants in all?","Write an addition sentence for Tray 1 that shows one number for each row.","Look at Tray 2. How many plants in all? Write the addition sentence for it.","Look at Tray 3. How many plants in all? Write the addition sentence for it.","Tray 1 and Tray 3 both hold 12 plants. What is different about the way they are set up?"],key:["4 rows with 3 plants in each row, 12 plants in all","3 + 3 + 3 + 3 = 12. One addend for each of the 4 rows","25 plants. 5 + 5 + 5 + 5 + 5 = 25","12 plants. 4 + 4 + 4 = 12","Tray 1 is 4 rows of 3 and Tray 3 is 3 rows of 4. The rows and the columns are swapped, and the total stays the same"]}]},{id:3,title:"The Long Row",short:"Long Row",parts:[{title:"Read the Story",std:["RF.2.4"],kind:"read",n:104,label:"words read correctly",dur:90,dir:"Read the story out loud. Use your best reading voice.",desc:"a 104-word grade-level story read aloud",html:()=>`<p class="passage g2-flu">${LAST_ROW}</p>`,key:["104 words. Mark each missed word and each self-correction on the passage in the record sheet.","Note pace and expression in your notes."]},{title:"Story Questions",std:["RL.2.1"],dur:80,dir:"Your teacher can read the story again if you need it. Then answer each question out loud.",desc:"asking and answering who, what, why, and how questions about key details in a story",html:()=>`<details class="look-back g2-story" open style="margin-bottom:10px"><summary>The Long Row (click to open or close the story)</summary><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${LAST_ROW}</p></details>`,after:view=>{const d=view.querySelector("details.g2-story");if(d&&view.querySelector(".g2-flu"))d.open=false},qs:["Who was still working when the light started to go?","Why did nobody want the row at the bottom of the hill?","What did Tess hear when she was halfway down the row?","How did the six people work once they got to the row?","Your turn. Ask a question about the story. Start with who, what, where, when, why, or how."],key:["Tess","The hose would not stretch that far, so every bucket of water had to be carried by hand.","The garden gate swinging open, which was the six people arriving.","They spread out along the row and worked from both ends in toward the middle.","Asks a question that is about this story and starts with a question word (for example: When did the six people come? Where was Tess standing?)."]}]},{id:4,title:"The Crow and the Badger",short:"The Hedge",parts:[{std:["RL.2.2"],n:4,dur:85,dir:"Read the story out loud. Then answer each question out loud.",desc:"recounting a fable and determining its central message or lesson",html:()=>passage("The Crow and the Badger",HEDGE),qs:["Tell me what happened in this story, from the beginning to the end.","What did the crow give the badger, and what did the badger give the crow?","What is the lesson of this story? Say it in one sentence.","The story says neither of them ever counted. Why does that matter to the lesson?"],key:["Retells it in order: all summer the crow passed shiny things over the hedge, the badger passed beetles back, neither of them kept track, and when winter came the badger had the warmest burrow and the crow had plenty to eat. Count it correct when the beginning, the middle and the end are all there in order.","The crow gave shiny bits of foil and wire. The badger gave fat beetles.","Any sentence that names the idea: helping somebody without keeping score leaves you both better off, or give and it comes back to you. The story does not say the lesson out loud, so the student has to work it out.","Because they were not trading or keeping score. They each gave what the other one wanted, and the help came back anyway. If the student only retells that line, ask: So were they trading, or were they helping?"]}]},{id:5,title:"The Tool Library",short:"Tool Library",parts:[{std:["RI.2.1"],dur:80,dir:"Read about tool libraries. Then answer each question out loud.",desc:"asking and answering what, why, how long, and who questions about an informational text the student read",html:()=>passage("The Tool Library",TOOL_LIBRARY),qs:["What kinds of things are on the shelves of a tool library?","How long may you keep something you borrow?","Why does the writer say the idea makes sense?","Who teaches people how to use the tools safely?","Your turn. Ask a question about tool libraries. Start with who, what, where, when, why, or how."],key:["Drills, ladders and wheelbarrows","A week","Most tools sit still almost all of the time, so one shared ladder can do the work of thirty","The volunteers who work the counter","Asks a question that is about the topic and starts with a question word (for example: How much does it cost to join? Where is the nearest one?)."]}]},{id:6,title:"Fix the Club Note",short:"Club Note",parts:[{title:"Say It Right",std:["L.2.1"],dur:90,dir:"Say each answer out loud.",desc:"spoken grammar items (irregular past tense, irregular plural, reflexive pronoun, adverb, word order, joining two sentences)",qs:["Today we bring the tools back. Yesterday we ____.","One goose, two ____.","The club painted the new sign all by ____.","Which word fits? The gate shut ____ behind us. Is it quiet or quietly?","Mix-up! Put these words in order to make a sentence: <b>carried / the neighbors / the buckets</b>","Join these two sentences with the word <b>because</b>: We finished before dark. Six people came to help."],key:["brought","geese","themselves","quietly","The neighbors carried the buckets.","We finished before dark because six people came to help."]},{title:"Write It Right",std:["L.2.2"],dur:90,dir:"Write each answer on your paper and hold it up.",desc:"written conventions (capital letters in place names, an apostrophe for a possessive and a contraction, a comma in a letter greeting, spelling two patterns)",qs:["Fix this sentence: <b>we walked along elm street to the green hill garden</b>","The bucket belongs to the club. Write the missing word: <b>the ____ bucket</b>","This is the start of a letter. Write it and add the missing mark: <b>Dear Tess</b>","Write <b>should not</b> as one short word with an apostrophe.","Listen. Write the word your teacher says.","Listen. Write the second word your teacher says."],key:["We walked along Elm Street to the Green Hill Garden. (capital W to start, capital E and capital S in the street name, capital G, H and G in the garden name, and a period)","club’s (apostrophe before the s)","Dear Tess, (comma after Tess)","shouldn’t (apostrophe where the o of not comes out)","Say: “Thank. We said thank you at the gate.” The student writes thank (th plus nk).","Say: “Garden. The garden gate was open.” The student writes garden (two syllables, r-controlled ar)."]}]},{id:7,title:"Count Along the Path",short:"Skip Count",parts:[{std:["2.NBT.A.2"],dur:110,dir:"Count out loud.",desc:"counting within 1000 and skip-counting by 5s, 10s, and 100s",html:()=>`<p class="big" style="margin-top:0">The club sets a stepping stone every 5 paces along the garden path, so the counting goes 5, 10, 15, and on.</p>`,fig:()=>F.row(heartRow(6)),qs:["Skip count by 5s from 75 to 115.","Skip count by 10s from 240 to 310.","Count by ones from 795 to 804.","Skip count by 100s from 260 to 860.","Count back by 10s from 530 to 470."],key:["75, 80, 85, 90, 95, 100, 105, 110, 115. Watch the jump past 95.","240, 250, 260, 270, 280, 290, 300, 310. Watch the jump past 290.","795, 796, 797, 798, 799, 800, 801, 802, 803, 804. Watch the jump past 799.","260, 360, 460, 560, 660, 760, 860","530, 520, 510, 500, 490, 480, 470. Watch the step back past 500."]}]},{id:8,title:"Club Logbook Math",short:"Logbook",parts:[{std:["2.NBT.B.7"],dur:150,dir:"Solve each one on your paper. Show your work and hold it up. Say your answer.",desc:"adding and subtracting within 1000 with a place value strategy and relating it to a written method",html:()=>`<p class="big" style="margin-top:0">Every year the club writes down how many plants went into the ground across the whole hill.</p>`,qs:["Last year 268 plants went in on the east side and 357 on the west side. How many in all? Show how you added.","The club wants 500 plants in the ground this year. So far 236 are in. How many more are needed?","The club grew 419 seedlings in the greenhouse and 184 more on a windowsill. How many did they grow in all?","There were 803 pots stacked in the shed. The club used 467 of them. How many pots are still stacked?"],key:["625 plants (268 + 357 = 625). Listen for hundreds with hundreds, tens with tens, ones with ones, and for making a new ten and a new hundred.","264 more (500 - 236 = 264). This one needs two decomposes, so watch the work.","603 seedlings (419 + 184 = 603). A new ten and a new hundred are both made here.","336 pots (803 - 467 = 336). Two decomposes again, and the 0 in the tens place makes it harder."]}]},{id:9,title:"The Clock by the Gate",short:"Clocks",parts:[{title:"Read the Clock",std:["2.MD.C.7"],n:4,dur:120,dir:"Look at each clock. Say the time out loud.",desc:"telling time on an analog clock to the nearest five minutes",html:()=>`<p class="big" style="margin-top:0">The clock by the garden gate keeps the club on time.</p>`,fig:()=>clockRow(),key:["Clock A: 6:10, said as six ten or ten past six. The minute hand is on the 2, and one number mark is five minutes.","Clock B: 4:35, said as four thirty-five or twenty-five to five. The minute hand is on the 7. Watch for a student who says five thirty-five, because the hour hand has moved most of the way toward the 5.","Clock C: 1:50, said as one fifty or ten to two. The minute hand is on the 10. The hour hand is almost on the 2, so watch for two fifty.","Clock D: 9:25, said as nine twenty-five or twenty-five past nine."]},{title:"Write the Time",std:["2.MD.C.7"],n:5,dur:95,dir:"Write each answer on your paper and hold it up.",desc:"writing times to the nearest five minutes, using a.m. and p.m., and knowing minutes in an hour",fig:()=>F.row([F.digital("5:20"),"The digital clock in the shed"],[F.clock(10,55,200),"The gate clock later that day"]),qs:["Look at the digital clock. Write that time.","The club meets at that time in the evening. Write the time again and add a.m. or p.m.","Tess wakes up at six o'clock in the morning. Write that time with a.m. or p.m.","Look at the gate clock. Write that time.","How many minutes are there in one hour?"],key:["5:20","5:20 p.m. (evening is after noon, so it is p.m.)","6:00 a.m.","10:55 (the minute hand is on the 11, which is 55 minutes, and the hour hand is almost on the 11, so watch for 11:55)","60 minutes"]}]},{id:10,title:"The Seed Sale",short:"Money",parts:[{std:["2.MD.C.8"],n:5,dur:120,dir:"Look at the coins. Answer out loud. Write the money answers with a cents sign or a dollar sign.",desc:"solving word problems with dollar bills, quarters, dimes, nickels, and pennies",html:()=>`<p class="big" style="margin-top:0">The club sells seed packets by the gate and puts the money back into the garden.</p>`,fig:()=>F.row(F.coins(["Q","D","D","N","P"])),qs:["Count the coins in the picture. How much money is that?","Luz has 2 quarters and 3 dimes. How much money does she have?","A packet of seeds costs 45 cents. Dev pays with 2 quarters. How much change should he get?","The club sold 3 jars of jam for 2 dollars each. How much money did they take in?","Ines has 1 dollar. She spends 65 cents on a little plant. How much does she have left?"],key:["51¢ (a quarter is 25, two dimes are 20, a nickel is 5, a penny is 1: 25 + 10 + 10 + 5 + 1 = 51)","80¢ (2 quarters is 50 and 3 dimes is 30, so 50 + 30 = 80)","5¢ (2 quarters is 50, and 50 - 45 = 5)","$6 (2 + 2 + 2 = 6, or 3 groups of 2)","35¢ (1 dollar is 100 cents, and 100 - 65 = 35)"]}]},{id:11,title:"Shapes in the Beds",short:"Bed Shapes",parts:[{std:["2.G.A.1"],n:6,dur:100,dir:"Look at the shapes. Answer out loud. Then draw the last one on your paper.",desc:"identifying triangles, quadrilaterals, pentagons, hexagons and cubes by their angles and faces, and drawing a shape with given attributes",html:()=>`<p class="big" style="margin-top:0">The club laid out its garden beds in different shapes, and keeps the seed boxes stacked by the gate.</p>`,fig:()=>bedsFig(),qs:["What is the name of Bed 1? How many sides and angles does it have?","What is the name of Bed 2? How many sides and angles does it have?","What is the name of Bed 3? How many sides and angles does it have?","What is the name of Bed 4? How many sides and angles does it have?","Box 5 is a solid shape. What is it called, and how many faces does it have?","Draw a shape that has 4 angles but is not a square."],key:["A triangle. 3 sides and 3 angles","A quadrilateral. 4 sides and 4 angles. Calling it a trapezoid as well is a plus, because every trapezoid is a quadrilateral","A pentagon. 5 sides and 5 angles","A hexagon. 6 sides and 6 angles","A cube. 6 faces, and all 6 are equal squares","Any quadrilateral that is not a square: a rectangle, a trapezoid, a rhombus, or a four-sided shape with no equal sides. Count it correct when the shape is closed and has exactly 4 straight sides"]}]},{id:12,title:"Guide Dog Report",short:"Listen",parts:[{std:["SL.2.2"],n:4,dur:65,read:GUIDE_DOG,dir:"Listen first. Then answer your teacher's questions out loud.",desc:"recounting and describing key ideas and details from a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${ic("ear",96)} ${ic("dog",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read a report about dogs that are trained to help people.</p>`,key:["Ask: Who does a guide dog live with for its first year? (a volunteer family, not the person it will one day lead)","Ask: Describe what that family's job is. (to make the puppy calm and friendly everywhere, taking it on car rides, into crowds, into lifts and onto loud streets)","Ask: What is intelligent disobedience? (when the person says forward and a car is coming, the dog refuses and stands still)","Say: Tell me two more things you learned. (any two: training at the school takes about five months, the dog starts learning as a puppy, intelligent disobedience is the hardest thing it learns, the first year is with a volunteer family)"]}]},{id:13,title:"The Bucket Log",short:"Bucket Log",parts:[{std:["W.2.8"],dur:85,dir:"Use the log to answer. Say the first two answers out loud. Write number 3 on your paper and hold it up. Then say number 4.",desc:"gathering information from a provided log and recalling information from experience to answer questions",html:()=>`<p class="big" style="margin-top:0">The club writes down how many buckets of water got carried each day, and how many people came to help.</p>`,fig:()=>F.row([heartSvg(68,PINK),"One paper heart"],LOG),qs:["Use the log. Which day did the club carry the most buckets?","Which days did more than 5 people come?","A friend asks, “Did more buckets get carried on Monday or on Thursday?” Write one sentence that answers your friend. Use the log.","Now use what you remember. Think of a time you worked on something with a group. What was the job, and what made it go faster or slower? Say it in a sentence."],key:["Tuesday, with 20 buckets","Tuesday and Thursday (7 people and 6 people)","The sentence says Thursday and uses the numbers from the log (Thursday had 16 and Monday had 12).","Tells one thing remembered from a real group job, in a sentence that answers the question (for example: We cleaned up the yard, and it went faster because everybody took one corner.)."]}]},{id:14,title:"Write It Down",short:"Write",parts:[{wk:"opinion",alt:{group:"write",label:"Wheelbarrow or Bench",icon:"💬",hint:"State an opinion and give reasons"},std:["W.2.1"],n:5,label:"checks met",dur:150,dir:WRITE_DIR,desc:"an opinion piece with reasons, linking words, and a concluding statement",html:()=>`<p class="big">The club has saved enough money for one thing. It can buy a wheelbarrow that everybody shares, or it can build a bench by the gate where people can sit and talk. Which should the club pick? Write your opinion. Give 2 reasons. Use the word <b>because</b>. End with a sentence that sums it up. Write 4 or 5 sentences.</p>${pills("I think","because","also","So")}`,key:["Introduces the topic: what the club is choosing between","States a clear opinion, the wheelbarrow or the bench","Supplies at least 2 reasons that support the opinion","Uses a linking word such as because, and, or also to connect the opinion to the reasons","Ends with a concluding statement, such as: So the club should buy the bench","Only the challenge the student picks gets rated here. If your curriculum lists both W.2.1 and W.2.2, the other prompt works as a follow-up on paper another day, and the record sheet shows the unpicked one as unrated."]},{wk:"facts",alt:{group:"write",label:"How Neighbors Help",icon:"📖",hint:"Introduce a topic and give facts"},std:["W.2.2"],n:5,label:"checks met",dur:150,dir:WRITE_DIR,desc:"an informative piece with an introduced topic, facts, a definition, and a concluding statement",html:()=>`<p class="big">Write about one way neighbors help each other, such as a shared garden, a tool library, or watching a pet while somebody is away. Introduce your topic in the first sentence. Give 2 or 3 facts. Explain what the thing is, so a reader who has never heard of it would understand. End with a closing sentence. Write 4 or 5 sentences.</p>${pills("A ____ is","One fact is","Another thing is","That is why")}`,key:["Introduces the topic in the first sentence, so the reader knows what the piece is about","Gives at least 2 facts about it","Includes a definition or an explanation of what the thing is","The facts fit the topic and are true","Ends with a concluding statement or section","Only the challenge the student picks gets rated here. If your curriculum lists both W.2.1 and W.2.2, the other prompt works as a follow-up on paper another day, and the record sheet shows the unpicked one as unrated."]}]},{id:15,title:"Read the Garden Signs",short:"Signs",parts:[{std:["RF.2.3"],n:3,dur:55,dir:"Read each line out loud. Sound out any word that is tricky.",desc:"applying grade-level phonics and word-analysis skills to decode words in text",html:()=>`<ol class="qlist" style="font-size:1.6rem;line-height:1.9"><li>We shared the heavy buckets and finished before dark.</li><li>Tess unpacked eight trays and wrote down every row.</li><li>The greenhouse was warm enough for the tiny sprouts.</li></ol>`,key:["Line 1: listen for the -ed ending said as /d/ in shared, the ea team saying short e in heavy, the ck plus -ed said as /t/ in buckets, and the r-controlled ar in dark.","Line 2: listen for the prefix un plus the -ed ending said as /t/ in unpacked, the irregular eigh in eight, and silent w plus final e in wrote.","Line 3: listen for the compound word greenhouse, the irregular ough said as /uf/ in enough, and the three-letter blend plus ou in sprouts."]}]},{id:16,title:"Pot and Bucket Problems",short:"Problems",parts:[{std:["2.OA.A.1"],n:3,dur:55,dir:"Solve each one on your paper. Say your answer.",desc:"one-step and two-step word problems within 100, with the unknown in different places",qs:["There were 46 paper hearts on the string. Some blew off in the wind. Now there are 29. How many blew off?","The club filled 38 pots on Saturday and 26 more on Sunday. Then they gave 15 pots to the school. How many pots do they still have?","Some people were waiting at the gate. Then 9 more came. Now there are 23. How many were waiting at the start?"],key:["17 hearts (46 - 29 = 17, or 29 + 17 = 46)","49 pots. Two steps: 38 + 26 = 64, then 64 - 15 = 49","14 people (23 - 9 = 14, or 14 + 9 = 23)"]}]},{id:17,title:"Odd or Even",short:"Odd Even",parts:[{std:["2.OA.C.3"],n:3,dur:50,dir:"Look at the two groups. Answer out loud. Write the last answer on your paper.",desc:"telling odd from even by pairing, and writing an even number as a sum of two equal addends",fig:()=>F.row(pairFig()),qs:["Count Group A. Is that number odd or even? How do you know?","Count Group B. Is that number odd or even? How do you know?","Write an equation that shows Group A as two equal numbers added together."],key:["14, and it is even. Every heart has a partner underneath it, with none left over","9, and it is odd. The last heart on the top row has no partner underneath","7 + 7 = 14. Both addends have to be the same, and they have to match the picture"]}]},{id:18,title:"Numbers in the Logbook",short:"Place Value",parts:[{title:"What the Digits Mean",std:["2.NBT.A.1"],n:3,dur:45,dir:"Answer out loud.",desc:"place value in three-digit numbers, and knowing 100 as ten tens",qs:["The club wrote 462 in the logbook. What does the 4 stand for? What does the 6 stand for? What does the 2 stand for?","How many tens are in 100?","What is 300 made of? Say it in hundreds, tens, and ones."],key:["4 hundreds, 6 tens, and 2 ones. Saying four hundred, sixty, and two is also correct","10 tens","3 hundreds, 0 tens, and 0 ones"]},{title:"Three Ways to Write It",std:["2.NBT.A.3"],n:3,dur:45,dir:"Write each answer on your paper and hold it up.",desc:"reading and writing numbers to 1000 in numerals, in words, and in expanded form",qs:["Write 608 in words.","Write four hundred twenty using numerals.","Write 573 in expanded form."],key:["six hundred eight. Watch for six hundred and eight, which is how it is said out loud, and for six hundred eighty","420. Watch for 4020","500 + 70 + 3"]}]},{id:19,title:"Measure It",short:"Measure",parts:[{std:["2.MD.A.1"],n:3,dur:50,dir:"Look at the ruler. Answer out loud. Then measure one real thing.",mats:["a ruler"],desc:"measuring length with a ruler and choosing the right tool for the job",fig:()=>F.row(F.ruler({length:12,item:5,itemLabel:"trowel",unit:"inches"})),qs:["How long is the trowel on the ruler?","You want to measure how long the garden path is. Would you use this 12-inch ruler or a measuring tape? Why?","Pick one thing near you. Measure it with a ruler. Tell me how long it is and what unit you used."],key:["5 inches. The trowel starts at 0 and ends at the 5 mark","A measuring tape, because the path is much longer than the ruler and a tape can reach all the way without being moved over and over","Names a real object, a number, and a unit, such as: My book is 9 inches long. Lining the object up with the 0 mark is the thing to watch"]}]},{id:20,title:"The Log as a Graph",short:"Bar Graph",parts:[{title:"Read the Bar Graph",std:["2.MD.D.10"],n:3,dur:55,dir:"Look at the graph. Answer out loud.",desc:"reading a bar graph with four categories and solving compare and put-together problems from it",html:()=>`<p class="big" style="margin-top:0">The club turned the people column of the Bucket Log into a bar graph.</p>`,fig:()=>F.barGraph({cats:["Mon","Tue","Wed","Thu"],vals:[4,7,3,6],max:8,step:1,title:"People who came to help"}),qs:["How many more people came on Tuesday than on Wednesday?","How many people came in all across the four days?","Monday and Wednesday together, is that more or fewer people than Thursday? By how many?"],key:["4 more (7 - 3 = 4)","20 people (4 + 7 + 3 + 6 = 20)","More, by 1. Monday and Wednesday together are 4 + 3 = 7, and Thursday is 6"]},{title:"Tell It Out Loud",std:["SL.2.4"],n:3,label:"checks met",dur:50,dir:"Talk for about one minute. Speak clearly, in full sentences.",desc:"recounting an experience out loud with facts and descriptive details",html:()=>`<p class="big">Tell me about somebody who taught you how to do something. What were you learning? What did that person say or do?</p>`,key:["Recounts a real experience with facts: who it was, what was being learned","Adds descriptive details that fit, such as where it happened or what the person said","Speaks audibly in full sentences that hang together. If the answer is one or two words, ask once: Can you tell me more about it?"]}]},{id:21,title:"A Time I Gave a Hand",short:"Narrative",parts:[{wk:"story",std:["W.2.3"],n:3,label:"checks met",dur:70,dir:WRITE_DIR,desc:"a short narrative recounting one event in order, with details and a closing",html:()=>`<p class="big">Write about one time you gave somebody a hand, or somebody gave you one. Tell what happened first and what happened next. End by telling how it turned out. Write 3 sentences.</p>${pills("One day","First","Then","In the end")}`,key:["Recounts one event, not a list, and tells two or more things that happened in an order that makes sense (W.2.3)","Includes details about what happened, what was said, or how it felt (W.2.3)","Uses a time word such as first, then, next, or after that, and ends with a sense of closure (W.2.3)","Three sentences is the whole job here. Do not ask for more."]}]},{id:22,title:"Three Trays in the Club Greenhouse",short:"Plant Test",parts:[{std:["2-LS2-1"],n:3,dur:90,dir:"Read the chart. Then answer out loud.",desc:"reading the results of a plant test and planning a fair test of one thing a plant needs",html:()=>`<p class="big">The garden club started three trays of lettuce on the same day so the members could see for themselves what a seedling needs.</p>
     <table class="bigTable"><tr><th>Tray</th><th>What it got</th><th>After two weeks</th></tr>
     <tr><td>A</td><td>under the greenhouse glass, watered</td><td>24 strong seedlings, dark green</td></tr>
     <tr><td>B</td><td>under the greenhouse glass, not watered</td><td>3 seedlings, all wilted flat</td></tr>
     <tr><td>C</td><td>under a cardboard box, watered</td><td>19 seedlings, tall, floppy and pale</td></tr></table>
     <div class="figure">${ic("sprout",88)}${ic("wateringCan",88)}</div>`,qs:["Which tray did best, and what did it get?","Tray C had 19 seedlings, nearly as many as tray A. Why would the club still say tray C failed?","You want to test only whether lettuce needs water. Name two things you would keep the same, and name the one thing you would change."],key:["Tray A, 24 strong dark green seedlings. It got both light and water.","Because they are tall, floppy and pale. Under the box they had no light, so they stretched looking for it and could not make food or go green. They would not survive being planted out.","Keep the same: the same seeds, the same tray, the same soil, the same spot under the glass. Change only one thing: one tray watered and one tray not watered. Changing two things is not a fair test, so ask again."]},{std:["2-LS2-2"],n:2,dur:90,dir:"Draw your model on your paper. Then tell your teacher about it.",desc:"making a simple model that does the job an animal does when it pollinates plants",html:()=>`<p class="big">Butterflies land on the club's flowers to drink. Pollen catches on their legs and comes off again on the next flower. That is how the flowers make seeds.</p>
     <div class="figure">${ic("butterfly",88)}${ic("daisy",88)}</div>
     <p class="big">Draw a model you could really build from things in a shed, such as two pipe cleaners bent into legs on a cork, that would collect pollen from one flower and leave some of it on another.</p>`,qs:["Draw your model. Label the part that collects the pollen and show how it gets left behind.","Which animal job does your model copy, and why does your model have to leave some pollen behind instead of keeping all of it?"],key:["Any model with a fuzzy or sticky collecting part and a way for some to come off: pipe cleaner legs on a cork, a felt pad, a soft brush. The two labeled parts are what to look for.","It copies a butterfly moving pollen between flowers. If the model kept every grain, the second flower would get none, and a flower needs pollen from another flower to make seeds."]}]},{id:23,title:"The Fern Corner and the Open Bed",short:"Two Places",parts:[{std:["2-LS4-1"],n:3,dur:90,dir:"Read both lists. Answer out loud.",desc:"comparing the kinds of living things found in two different habitats",html:()=>`<p class="big">Club members counted what was living in two corners of the same garden, half an hour in each.</p>
     <table class="bigTable"><tr><th>The shady damp fern corner</th><th>The sunny open bed</th></tr>
     <tr><td>3 kinds of fern</td><td>4 kinds of flower</td></tr>
     <tr><td>2 kinds of moss</td><td>2 kinds of bee</td></tr>
     <tr><td>2 kinds of slug and snail</td><td>1 kind of butterfly, 1 ladybug</td></tr>
     <tr><td>1 kind of woodlouse</td><td>1 kind of grasshopper</td></tr></table>
     <div class="figure">${ic("bee",80)}${ic("snail",80)}</div>`,qs:["How many kinds of living things are on each list?","Name one living thing from the fern corner that would not do well in the sunny bed, and say why.","Both corners are in the same garden and get the same rain. Why are the two lists so different?"],key:["Both have 8. The fern corner has three ferns, two mosses, two slugs and snails and one woodlouse. The sunny bed has four flowers, two bees, one butterfly, one ladybug and one grasshopper.","Any sensible pick with a reason: a slug would dry out in the sun because its body has to stay damp, moss needs shade and damp or it shrivels, a fern burns in strong sun.","Because one corner is shady and damp and the other is sunny and dry, and living things live where they can get what they need. Note that the number of kinds is the same here: the two places are not better or worse, they are different."]}]},{id:24,title:"One Storm, or Many Winters",short:"Fast or Slow",parts:[{std:["2-ESS1-1"],n:3,dur:90,dir:"Read both notes. Answer out loud.",desc:"using two sources as evidence that some Earth events happen quickly and some happen slowly",html:()=>`<p class="big">Two notes about the club's land, from two different places.</p>
     <table class="bigTable"><tr><th>Where it came from</th><th>What it says</th></tr>
     <tr><td>the club meeting notes</td><td>One storm in March washed the gravel off the whole top path in an afternoon and dropped it at the gate.</td></tr>
     <tr><td>a card on the big rock by the gate</td><td>Water seeped into a crack in this rock, froze each winter, and pushed it a little wider. After many winters it split along that line.</td></tr></table>`,qs:["Which note tells about a change that happened in one afternoon?","Which note tells about a change that took many years?","Name one more change to the land that happens quickly, and one that happens slowly."],key:["The club meeting notes, the gravel washed off the top path in an afternoon.","The card on the big rock, the rock split after many winters of freezing water.","Quick: a flood, a rockfall, a bank falling in, a tree pushed over in a storm. Slow: a stream cutting a valley, a cliff wearing back, a hill wearing down. The answer has to name a change to the land, not just a kind of weather."]},{std:["2-ESS2-3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling where water is found on Earth and whether it is solid or liquid",html:()=>`<p class="big">The club keeps track of every bit of water on its land, because it shares it.</p>
     <div class="figure">${ic("drop",80)}${ic("cloud",80)}${ic("snowflake",80)}</div>`,qs:["Name three places on this garden land where you would find water.","Most of the water on Earth is in the ocean and it is salty. Where does the club's water come from, and is it salty or fresh?","Sort these four into solid water and liquid water: the ice in the bird bath, the rain in the barrel, the frost on the glass, the water in the pond."],key:["Any three: the rain barrel, the pond, the bird bath, the tap on the pipe, clouds, frost or ice, in the soil, inside the plants.","From rain caught in the barrel and from the town pipe. It is fresh, which is why plants can be watered with it. Salty water would kill them.","Solid: the ice in the bird bath and the frost on the glass. Liquid: the rain in the barrel and the water in the pond."]}]},{id:25,title:"Holding the Beds, and a Map of the Garden",short:"The Land",parts:[{std:["2-ESS2-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"comparing two things built to stop wind from blowing the soil away",html:()=>`<p class="big">Dry wind lifts the loose soil out of the raised beds along the open side of the garden. Two screens were tried and the soil that had to be put back was weighed.</p>
     <table class="bigTable"><tr><th>What stood on the windy side</th><th>Soil put back after one month</th></tr>
     <tr><td>nothing</td><td>8 kilograms</td></tr>
     <tr><td>a woven willow fence</td><td>3 kilograms</td></tr>
     <tr><td>a row of low shrubs</td><td>1 kilogram</td></tr></table>`,qs:["Which screen held the soil best?","How do you know, using the numbers in the chart?","The fence went up in one afternoon and the shrubs took two years to get that thick. Which would you put in first, and why?"],key:["the row of low shrubs","Only 1 kilogram had to be put back behind the shrubs, 3 kilograms behind the willow fence, and 8 kilograms where there was nothing. The reason must come from the numbers.","Either answer works with a reason: the fence first because it helps straight away while the shrubs grow, or the shrubs first because they end up holding the most. Listen for the reason, not the choice."]},{std:["2-ESS2-2"],n:3,dur:90,dir:"Draw on your paper and hold it up.",desc:"making a model of an area that shows the shapes of the land and the bodies of water in it",html:()=>`<p class="big">Make your own model map of the club's land. Put in the mound of earth at the back, the flat bed area, the pond, and the ditch that carries rain away. Add a key that says which is which.</p>
     <div class="figure">${ic("map",88)}${ic("mountain",88)}${ic("purpleFlower",88)}</div>`,qs:["Draw your model map with the mound, the flat beds, the pond and the ditch on it.","Show me your key. Which parts are land and which parts are water?","Water runs downhill. Looking at your own map, where does rain falling on the mound end up?"],key:["All four on the page and told apart by shape or color: the mound as a bump or as rings, the beds left flat, the pond as a closed shape, the ditch as a line.","Points to each part and reads the key. The key is what makes this a model and not just a picture.","Down the mound and along the ditch, usually into the pond or off the land. The answer has to match their own drawing, so follow their finger."]}]},{id:26,title:"Sorting the Tool Library",short:"Materials",parts:[{std:["2-PS1-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"describing materials by properties you can see or feel and sorting them into groups",html:()=>`<p class="big">The club lends out its tools to anyone who joins. Four things off the shelf, and what was noticed about each.</p>
     <table class="bigTable"><tr><th>Item</th><th>Material</th><th>What was noticed</th></tr>
     <tr><td>a trowel</td><td>steel</td><td>hard, shiny, cold, does not bend</td></tr>
     <tr><td>a glove</td><td>rubber</td><td>bends, stretches, keeps water out</td></tr>
     <tr><td>a seedling pot</td><td>clay</td><td>hard, rough, breaks if dropped, soaks water up</td></tr>
     <tr><td>an apron</td><td>cotton</td><td>soft, bends easily, soaks water up</td></tr></table>`,qs:["Sort the four items into a hard group and a group that bends.","Two of them soak water up. Which two, and which of those two would hold water in it for a plant?","Name one more property from the chart you could sort these four by, and sort them by it."],key:["Hard: the steel trowel and the clay pot. Bends: the rubber glove and the cotton apron.","The clay pot and the cotton apron. The clay pot, because it is a container that holds its shape, while the apron just gets wet.","Any property that can be seen or felt and that really splits the four: breaks if dropped or does not, shiny or dull, rough or smooth, keeps water out or soaks it up. The groups have to match the property named."]},{std:["2-PS1-2"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"using test data to choose the material that suits a job",html:()=>`<p class="big">The tool library needs bags so members can carry borrowed tools home. Three materials were each loaded with a trowel, a fork and a watering can and carried a mile in the rain.</p>
     <table class="bigTable"><tr><th>Material</th><th>Held the weight</th><th>Tools dry at the end</th></tr>
     <tr><td>paper sack</td><td>no, the bottom gave way</td><td>no</td></tr>
     <tr><td>cotton tote</td><td>yes</td><td>no</td></tr>
     <tr><td>coated canvas tote</td><td>yes</td><td>yes</td></tr></table>`,qs:["Which material should the lending bags be made of?","Which two pieces of the chart make you sure?","The cotton tote held the weight perfectly well. Why would the club still not use it?"],key:["the coated canvas tote","It held the weight and the tools were dry at the end. Both columns have to be used, not just one.","The tools came home wet, and wet steel tools go rusty. A bag that holds the weight but lets the rain in spoils the tools everyone shares."]}]},{id:27,title:"Taken Apart, Heated, Cooled",short:"Heat and Cold",parts:[{std:["2-PS1-3"],n:2,dur:75,dir:"Answer out loud. You may draw if it helps.",desc:"telling how a thing built from a few pieces can be taken apart and built into something new",html:()=>`<p class="big">The bench is by the greenhouse. It is made of 3 long planks. It has 2 solid blocks. 8 bolts hold it together. The club unbolted it to move it.</p>
     <div class="figure">${ic("board",88)}${ic("box",88)}</div>`,qs:["The bench is gone. Are the planks and blocks gone too? What is on the grass now?","Build something new in your head out of those 3 planks and 2 blocks. What is it, and how do the pieces go together?"],key:["No. All 3 planks, both blocks and all 8 bolts are still there. They are the same pieces, just not bolted together as a bench any more.","Any real thing from 3 planks and 2 blocks: a potting table, a frame for a raised bed, a step, a shelf, a ramp for a wheelbarrow, a sign. Listen for how the pieces join, because that is the evidence the same set of pieces made something different."]},{std:["2-PS1-4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"arguing with evidence that some heating and cooling changes can be undone and some cannot",html:()=>`<p class="big">Two things happened in the club kitchen on the same afternoon.</p>
     <table class="bigTable"><tr><th>What happened</th></tr>
     <tr><td>A lump of beeswax was warmed in a pot to make hand salve and became a clear liquid.</td></tr>
     <tr><td>Sunflower seeds for the bird feeder were toasted in a hot pan and turned dark brown and nutty.</td></tr></table>
     <div class="figure">${ic("honey",80)}${ic("pan",80)}</div>`,qs:["Take the pot of melted beeswax off the heat and let it cool. What happens to it?","Let the toasted seeds cool right down. Do they go back to pale raw seeds?","Which of the two changes can be undone, and what is your evidence?"],key:["It goes solid again and is a lump of wax, in the shape of whatever it cooled in.","No. They stay dark brown and nutty. Cooling does nothing for them.","The beeswax change can be undone. The evidence is that the wax goes solid again when it cools and melts again when it is warmed, while the toasted seeds never go back however cool they get. Listen for the student using what happened, not just saying yes or no."]}]},{id:28,title:"The Tools That Go Missing",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Read the note. Answer out loud.",desc:"naming a problem people want to fix and asking a question about it",html:()=>`<p class="passage">The club keeps its small hand tools together. They go in one deep bucket. It sits by the shed door. Members dig through the bucket. They try to find what they want. The tools end up at the bottom. Soil falls off them. The tools sit under it. Last week three trowels went missing. They could not be found at all. Nobody could tell. They had been borrowed or buried.</p>`,qs:["What is the problem the club wants to fix? Say it in one sentence.","Ask one question that would help you fix it."],key:["The tools get lost at the bottom of one deep bucket and nobody can tell what has been borrowed. Naming the losing track of tools, not the digging, is the problem.","Any real question: how many tools are there, how many kinds, how long are they, how many members borrow at once, is there a wall to hang them on. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw on your paper and hold it up.",desc:"drawing a design and telling how its shape does the job",html:()=>`<p class="big">Draw something that would hold the hand tools so anyone can see at a glance what is there and what is gone. Think hard about its shape.</p>
     <div class="figure">${ic("board",88)}${ic("hand",88)}</div>`,qs:["Draw your fix.","Tell me how the shape of what you drew shows at a glance that a tool is missing."],key:["Any design that gives each tool its own place: a board with hooks, a rack with slots, a drawn outline for each tool, a row of open tubes, labeled boxes.","The shape is the part being checked. Something like: each tool has its own hook, so an empty hook shows one is gone; the outline shows the shape that belongs there; a slot with nothing in it is easy to see."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Read the chart. Answer out loud.",desc:"comparing test results from two designs built for the same problem",html:()=>`<p class="big">The club tried both ideas for one month each.</p>
     <table class="bigTable"><tr><th>Fix</th><th>Tools missing at the end of the month</th><th>How long it took to find a trowel</th></tr>
     <tr><td>a board with a hook and an outline for each tool</td><td>0</td><td>a few seconds</td></tr>
     <tr><td>four labeled buckets instead of one</td><td>2</td><td>about half a minute</td></tr></table>`,qs:["Which fix worked better?","How do you know? Use both columns."],key:["the board with a hook and an outline for each tool","No tools were missing and a trowel took only a few seconds to find, while the buckets lost 2 tools and took about half a minute. Both columns have to be used, not just the missing tools."]}]},{id:29,title:"Sharing Then and Now",short:"Long Ago",parts:[{std:["HSS-2.1"],n:3,dur:75,dir:"Read the four lines. Answer out loud.",desc:"telling things that happened long ago from things that happened in the last day or two",html:()=>`<p class="big">Four lines from the club's record book.</p>
     <table class="bigTable"><tr><th>Line</th><th>What it says</th></tr>
     <tr><td>1</td><td>This morning four members weeded the shared bed by the gate.</td></tr>
     <tr><td>2</td><td>Long ago the families on this street carried their water from one hand pump at the corner.</td></tr>
     <tr><td>3</td><td>Yesterday the club lent out nine tools and all nine came back.</td></tr>
     <tr><td>4</td><td>Before there were seed shops nearby, neighbors here saved seeds each autumn and swapped them in spring.</td></tr></table>`,qs:["Which two lines tell about things that happened long ago?","Which two tell about things that happened in the last day or two?","Pick one of the long ago lines and say what is different about the way it is done now."],key:["Lines 2 and 4, carrying water from one hand pump and swapping saved seeds.","Lines 1 and 3, weeding this morning and lending the tools yesterday.","Either one: water comes out of a tap in every house now instead of from one pump at the corner; seeds can be bought in a shop or online instead of only being saved and swapped. A student who says people still swap seeds is right too, as long as they say what else is possible now."]}]},{id:30,title:"Where Things Are in the Garden",short:"Garden Map",parts:[{std:["HSS-2.2"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"giving an exact place on a map with a letter and a number, and using north, south, east, west and between",html:()=>`<p class="big">The club garden, drawn in nine squares. North is at the top.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("mountain",46)} big hill</td><td>${ic("bee",46)} bee hotel</td><td>${ic("birdhouse",46)} bird feeders</td></tr>
     <tr><th>B</th><td>${ic("books",46)} tool library</td><td>${ic("purpleFlower",46)} shared beds</td><td>${ic("herb",46)} herb rows</td></tr>
     <tr><th>C</th><td>${ic("drop",46)} pond</td><td>${ic("box",46)} compost bins</td><td>${ic("wateringCan",46)} rain barrels</td></tr></table>
     <p class="big">${ic("compass",56)} North is up, south is down, east is to the right, west is to the left.</p>`,qs:["Give the exact square the shared beds are in, using their letter and number.","What is directly south of the shared beds?","Is the tool library east or west of the herb rows?","Which square is between the pond and the rain barrels?"],key:["B2","the compost bins, in square C2","west. The tool library is in B1 and the herb rows are in B3, so the tool library is to the left, which is west.","C2, the compost bins"]}]},{id:31,title:"Rules, Money and the Seed Sale",short:"Rules and Money",parts:[{std:["HSS-2.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling who makes rules at each level here, and how another country chooses a leader differently",html:()=>`<p class="big">The club has its own rules. They are written down. The members agreed them by a vote. The club also follows the rules of the city.</p>
     <div class="figure">${ic("flag",80)}${ic("hands",80)}</div>`,qs:["The club votes on whether to open the garden on Saturday mornings. 11 members vote yes and 4 vote no. What happens, and why?","Who makes the laws for a whole city? A city council the people elect, or the oldest person in the city?","In some other countries the leader is a king or a queen who was born into the job. In our country, how do we get our leaders?"],key:["The garden opens on Saturday mornings. More members voted yes than no, and that is how a vote is decided.","a city council the people elect. Accept: the mayor and the city council.","We vote for them. Any answer that says the people choose their leaders by voting counts."]},{std:["HSS-2.4"],n:3,dur:90,dir:"Read the price list. Answer out loud.",desc:"telling goods from services, spending a set amount, and saying why people trade",html:()=>`<p class="big">The club's spring seed sale, held to pay for new tools.</p>
     <table class="bigTable"><tr><th>What is on offer</th><th>Price</th></tr>
     <tr><td>a packet of flower seeds</td><td>25 cents</td></tr>
     <tr><td>a seedling in a pot</td><td>40 cents</td></tr>
     <tr><td>a bag of compost</td><td>60 cents</td></tr>
     <tr><td>a member to come and plant it for you</td><td>35 cents</td></tr></table>
     <div class="figure">${ic("purpleFlower",72)}${ic("sprout",72)}</div>`,qs:["Three things on this list are goods and one is a service. Which one is the service, and how do you know?","You have 65 cents. Name two things you could buy with it, and say what you give up.","The club grows seedlings but buys its compost. Why do people trade instead of making everything themselves?"],key:["A member coming to plant it for you. It is work someone does for you, not a thing you take home.","Any pair at 65 cents or less: seeds and a seedling is 65 cents, seeds and the planting is 60 cents, a seedling and the planting is 75 cents and is too much. The giving up is the part to listen for.","Because nobody can make everything. Each person or group makes what they can and trades for the rest. Accept: it saves time, you get what you cannot make yourself."]}]},{id:32,title:"Someone Who Made a Difference",short:"Made a Difference",parts:[{std:["HSS-2.5"],n:3,dur:90,dir:"Read about him. Answer out loud.",desc:"telling what one person from the past did, naming a character strength, and saying how it helped others",html:()=>`<p class="passage">Jackie Robinson was one of the best ballplayers. Anyone had seen that. But the big leagues would not sign him. He was a Black player. That went on for years. In 1947 he became the first. Crowds shouted unkind things at him. Even some of his own teammates did. It came from the stands and the bench. He had agreed not to answer back. So he let his playing speak. He kept his temper. He did it through a whole season. He was named rookie of the year. Other teams began signing Black players after him. Later he worked for fair treatment for others. He helped start a bank. It would lend to families. Other banks had turned them away.</p>
     <div class="figure">${ic("soccerBall",80)}${ic("heart",80)}</div>`,qs:["What did Jackie Robinson do in 1947 that no Black player had been allowed to do before?","Which word fits him best from what you read: dignified, rude, or careless? Say why.","Name one way what he did made a difference to other people."],key:["He played in the big leagues. He was the first Black player signed to a big league team.","dignified. Accept patient or strong with the same reasons. Any reason taken from the text: he kept his temper through a whole season, he let his playing answer for him instead of shouting back.","Any answer from the text: other teams began signing Black players after him, he worked for fair treatment, he helped start a bank that lent to families other banks turned away."]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Long Garden Words",std:["RF.3.3"],needs:["RF.2.3"],n:3,dir:"Read each long word out loud.",html:()=>`<div style="text-align:center">${["generous","community","unbelievable"].map(w=>`<p class="huge" style="font-size:clamp(2.4rem,8vw,4.4rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["generous (gen-er-ous, with a soft g)","community (com-mu-ni-ty)","unbelievable (un-be-liev-a-ble, prefix un- and suffix -able)"]},3:{id:"L3",title:"Level Up: Show Me the Words",std:["RL.3.1"],needs:["RL.2.1"],n:2,dir:"Answer out loud. Then read the words from the story that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${LAST_ROW}</p><ol class="qlist"><li>How do you know Tess had been left behind by everybody else? Read the part of the story that shows it.</li><li>How do you know the six people had come on purpose to help? Read the part that shows it.</li></ol>`,key:["Says the other rows were already done long before, and reads the line about every other row on the hill being weeded and watered hours earlier.","Says they each brought a bucket, and reads the line about six people coming through the gate, each one swinging an empty bucket. The line about spreading out along the row and working from both ends also counts."]},5:{id:"L5",title:"Level Up: Prove It",std:["RI.3.1"],needs:["RI.2.1"],n:2,dir:"Answer out loud. Then read the words from the text that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${TOOL_LIBRARY}</p><ol class="qlist"><li>How do you know a tool library saves people money? Read the part of the text that shows it.</li><li>How do you know a tool library does more than lend things out? Read the part that shows your answer.</li></ol>`,key:["Says one shared tool replaces many private ones, and reads the line about one shared ladder doing the work of thirty, or the line about a ladder costing the same whether it gets used twice a year or every day.","Reads the last line, about volunteers at the counter teaching people how to use the tools safely."]},6:{id:"L6",title:"Level Up: Grown-Up Grammar",std:["L.3.1"],needs:["L.2.1"],n:2,dir:"Say each answer out loud.",html:()=>`<ol class="qlist"><li>One bucket is heavy. A bucket with water in it is ____ than an empty one.</li><li>Join these two sentences with the word <b>although</b>: The light was going. We finished the row.</li></ol>`,key:["heavier (the comparative form)","Although the light was going, we finished the row. (Or: We finished the row although the light was going.)"]},9:{id:"L9",title:"Level Up: How Long Did It Take",std:["3.MD.A.1"],needs:["2.MD.C.7"],n:2,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">The club started carrying water at 5:15 p.m. and stopped at 6:05 p.m.</p><ol class="qlist"><li>How many minutes did the work take?</li><li>The next day they started at 4:50 p.m. and worked for 40 minutes. What time did they stop?</li></ol>`,key:["50 minutes (5:15 to 6:00 is 45 minutes, then 6:00 to 6:05 is 5 more)","5:30 p.m. (4:50 plus 10 minutes is 5:00, plus 30 more is 5:30)"]},11:{id:"L11",title:"Level Up: Cut It Into Fourths",std:["3.G.A.2"],needs:["2.G.A.1"],n:2,dir:"Look at the bed. Answer out loud, then draw on your paper.",html:()=>`<div class="figure">${F.gridRect(2,2,0,{cell:70})}</div><ol class="qlist"><li>This square bed is cut into 4 equal parts. What fraction of the whole bed is one part?</li><li>Draw the same square bed, but cut it into 4 equal parts a different way. Say the fraction again.</li></ol>`,key:["One fourth, written 1/4. The 4 equal parts make the whole, so each one is 1/4 of it.","Any second way that really is 4 equal parts, such as 4 long strips side by side instead of 4 squares. It is still 1/4 each, because equal parts of the same whole are the same size however they are cut."]}};const PASSAGE_STD=["RL.2.1","RL.2.2","RI.2.1","RL.3.1","RI.3.1","2-LS2-1","2-LS2-2","2-LS4-1","2-ESS1-1","2-ESS2-1","2-ESS2-2","2-ESS2-3","2-PS1-1","2-PS1-2","2-PS1-3","2-PS1-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-2.1","HSS-2.2","HSS-2.3","HSS-2.4","HSS-2.5"];let chartOn={},pvVal=["",""],blk=[0,0,0];function chartHtml(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${chartOn[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function pvTable(){let h=`<tr><th>Hundreds</th><th>Tens</th><th>Ones</th></tr>`;pvVal.forEach((v,r)=>{if(r&&!v)return;h+="<tr>";for(let i=0;i<3;i++){const k=v.length-(3-i);h+=`<td>${k>=0?v[k]:""}</td>`}h+="</tr>"});return h}function pvHtml(){const inp=(i,t)=>`<label class="pv-in">${t}<input type="text" inputmode="numeric" maxlength="3" data-pv="${i}" value="${pvVal[i]}" autocomplete="off"></label>`;return inp(0,"Type a number")+inp(1,"Second number (if you need one)")+`<div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div><p class="small">Type a number up to 999. Each digit goes in its place.</p>`}function matSvg(h,t,o){return F.blocks(h,t,o)}function blkHtml(){const b=(k,t)=>`<button class="chip" data-b="${k}">${t}</button>`;return`<div class="blk-row">${b("h+","Add a hundred")}${b("h-","Take a hundred")}${b("t+","Add a ten")}${b("t-","Take a ten")}${b("o+","Add a one")}${b("o-","Take a one")}</div><div class="blk-row">${b("to","Trade 10 ones for a ten")}${b("th","Trade 10 tens for a hundred")}${b("bt","Break a ten into ones")}${b("bh","Break a hundred into tens")}${b("x","Clear")}</div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]+blk[2]?matSvg(blk[0],blk[1],blk[2]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} hundreds, ${blk[1]} tens, and ${blk[2]} ones on the mat.</p>`}function blkDo(k){const MAX=[9,19,19],i={h:0,t:1,o:2}[k[0]];if(k==="x")blk=[0,0,0];else if(k==="to"){if(blk[2]>=10&&blk[1]<19){blk[2]-=10;blk[1]++}}else if(k==="th"){if(blk[1]>=10&&blk[0]<9){blk[1]-=10;blk[0]++}}else if(k==="bt"){if(blk[1]>=1&&blk[2]<=9){blk[1]--;blk[2]+=10}}else if(k==="bh"){if(blk[0]>=1&&blk[1]<=9){blk[0]--;blk[1]+=10}}else blk[i]=Math.max(0,Math.min(MAX[i],blk[i]+(k[1]==="+"?1:-1)))}function coinHtml(){const row=(k,t)=>`<div style="display:flex;align-items:center;gap:12px;padding:6px 0">${F.coin(k)}<span style="font-family:var(--font-display);font-weight:700;font-size:1.3rem">${t}</span></div>`;return`<div style="width:fit-content;margin:0 auto">${row("P","penny = 1¢")}${row("N","nickel = 5¢")}${row("D","dime = 10¢")}${row("Q","quarter = 25¢")}</div><p class="small">1 dollar = 100¢</p>`}const STARTERS={"W.2.1":["I think the club should ____.","One reason is ____.","Also, ____.","So the club should ____."],"W.2.2":["A ____ is ____.","One fact is ____.","Another thing is ____.","That is why ____."],"W.2.8":["The log says ____.","On Tuesday the club carried ____.","The most buckets went on ____.","I remember ____."],"W.2.3":["One day ____.","First, ____.","Then, ____.","In the end ____."]};function sentHtml(st){const k=st&&st.parts&&st.parts[0]&&st.parts[0].std&&st.parts[0].std[0]||"W.2.1";return`<ul class="starters">${(STARTERS[k]||STARTERS["W.2.1"]).map(x=>`<li>${x}</li>`).join("")}</ul>`}let tpsNlStart="",tpsNlHops=[],tpsNlShown={};function tpsNlSvg(){if(tpsNlStart==="")return`<p class="small">Type the number to start at.</p>`;const vals=[+tpsNlStart];tpsNlHops.forEach(d=>vals.push(vals[vals.length-1]+d));const uniq=[...new Set(vals)].sort((a,b)=>a-b),gap=72,W=Math.max(320,50+(uniq.length-1)*gap+50),X=v=>50+uniq.indexOf(v)*gap,y=150;let s=`<svg viewBox="0 0 ${W} 200" width="${W}" role="img" aria-label="Open number line">`;s+=`<line x1="16" y1="${y}" x2="${W-16}" y2="${y}" stroke="var(--ink)" stroke-width="3"/><path d="M16 ${y} l9 -6 v12 Z M${W-16} ${y} l-9 -6 v12 Z" fill="var(--ink)"/>`;tpsNlHops.forEach((d,i)=>{const a=X(vals[i]),b=X(vals[i+1]),span=Math.abs(b-a)/gap,top=y-Math.min(120,34+span*26);s+=`<path d="M${a} ${y-10} Q${(a+b)/2} ${2*top-(y-10)} ${b} ${y-10}" fill="none" stroke="var(--sea)" stroke-width="3"/>`;s+=`<text x="${(a+b)/2}" y="${top-6}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--sea)">${d>0?"+":"−"}${Math.abs(d)}</text>`});uniq.forEach(v=>{const x=X(v),open=v===+tpsNlStart||tpsNlShown[v];s+=`<line x1="${x}" y1="${y-10}" x2="${x}" y2="${y+10}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<g ${v===+tpsNlStart?"":`data-tv="${v}" style="cursor:pointer"`}><rect x="${x-27}" y="${y+16}" width="54" height="30" rx="8" fill="${open?"var(--surface)":"var(--sea-soft)"}" stroke="var(--sea)" stroke-width="2" ${open?"":`stroke-dasharray="4 4"`}/><text x="${x}" y="${y+32}" font-size="19" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${open?v:"?"}</text></g>`});return s+"</svg>"}function tpsNlHtml(){const j=d=>`<button class="chip" data-tj="${d}">${d>0?"+":"−"}${Math.abs(d)}</button>`;return`<label class="pv-in">Start at<input type="text" inputmode="numeric" maxlength="3" id="tpsNlStart" value="${tpsNlStart}" autocomplete="off"></label><div class="blk-row">${[100,10,5,1].map(j).join("")}</div><div class="blk-row">${[-100,-10,-5,-1].map(j).join("")}<button class="chip" data-tj="u">Undo</button><button class="chip" data-tj="x">Clear</button></div><div class="tool-scroll" id="tpsNlBox" style="text-align:center">${tpsNlSvg()}</div><p class="small">Click a jump the student says. Each landing spot shows a ? until you click it. Click it after the student says the number.</p>`}function tpsNlBind(b,r){const box=()=>b.querySelectorAll("[data-tv]").forEach(g=>g.onclick=()=>{tpsNlShown[g.dataset.tv]=!tpsNlShown[g.dataset.tv];r()});const inp=b.querySelector("#tpsNlStart");inp.oninput=()=>{tpsNlStart=inp.value.replace(/[^0-9]/g,"");tpsNlShown={};b.querySelector("#tpsNlBox").innerHTML=tpsNlSvg();box()};b.querySelectorAll("[data-tj]").forEach(x=>x.onclick=()=>{const k=x.dataset.tj;if(k==="x"){tpsNlHops=[];tpsNlShown={}}else if(k==="u")tpsNlHops.pop();else if(tpsNlStart!==""&&tpsNlHops.length<10)tpsNlHops.push(+k);r()});box()}function tpsClockHtml(){return F.row([F.clock(8,50,170),"8:50"],[F.clock(2,15,170),"2:15, quarter past two"])+F.table(["Long hand points at","Minutes","How to say it"],[["12","00","o'clock"],["1","05","five past"],["2","10","ten past"],["3","15","quarter past"],["6","30","half past"],["9","45","quarter to the next hour"]])+`<ul class="frames"><li>Count by fives around the dial. Each numeral the long hand passes is five more minutes.</li><li>The short hand is the hour. When it sits between two numerals, say the smaller one.</li><li>a.m. is before noon. p.m. is after noon.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:70,parts:2,unit:"in",item:4.5,itemLabel:"pencil"}))+F.table(["Mark on the ruler","How to say it"],[["the long numbered mark","a whole inch: 1, 2, 3"],["the short mark halfway between two numbers","a half inch, like 4 1/2"]])+F.table(["To measure","Use"],[["something small, like a crayon","an inch ruler"],["a desk or a door","a yardstick or a meter stick"],["something round or bendy, like a wrist","a measuring tape"]])+`<p class="small">Line the left end of the object up with the 0, then read the mark the right end lands on. Write the number with its unit.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["silent e","the e makes the vowel say its name","froze, these, bike"],["ai, ea, ee, oa, ow, oo, ew, ou","a vowel team or a diphthong","tail, seal, boat, book, flew, crowd"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, north, fur"],["un-, re-, pre-","a prefix on the front","unpack, reread, preheat"],["-y, -ly, -ful, -er, -ed, -ing","a suffix on the end","windy, slowly, helpful, jumped"],["two syllables","split the word between its parts","camp / site, sun / set"],["thought, could, through","an irregular spelling","read these as whole words"]])+`<p class="chart-note">Cover the prefix and the suffix, read the middle, then put the word back together.</p>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","the beginning: who it is about and where","First, ____."],["2. Next","the middle: what happened, in order","Next, ____."],["3. Last","the end: how it turned out","Last, ____."],["4. Lesson","what the story teaches","The story teaches ____."]])+`<ul class="frames"><li>Add a fact that fits: where, when, who or what.</li><li>Add a describing detail: how it looked, felt or sounded.</li><li>Speak in whole sentences.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={chart:{name:"120 chart",std:["2.MD.C.8","2.MD.D.10","2.NBT.A.2","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4","3.MD.A.1","3.MD.B.3","3.OA.D.8"],html:chartHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{chartOn[x.dataset.n]=!chartOn[x.dataset.n];r()})},pv:{name:"Place value chart",std:["2.MD.C.8","2.NBT.A.1","2.NBT.A.2","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.4","3.OA.A.1"],html:pvHtml,bind:b=>b.querySelectorAll("[data-pv]").forEach(x=>x.oninput=()=>{pvVal[+x.dataset.pv]=x.value=x.value.replace(/[^0-9]/g,"");b.querySelector("#pvTable").innerHTML=pvTable()})},blocks:{name:"Hundreds, tens, and ones blocks",std:["2.NBT.A.1","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{blkDo(x.dataset.b);r()})},coins:{name:"Coin values",std:["2.MD.C.8"],html:coinHtml},sent:{name:"Sentence starters",std:["W.2.1","W.2.2","W.2.3","W.2.8"],html:sentHtml},nl:{name:"Open number line",std:["2.NBT.B.7","2.OA.A.1","3.OA.D.8"],html:tpsNlHtml,bind:tpsNlBind},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.2.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.2.2","SL.2.4","W.2.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","RI.2.1","RL.2.1"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.2.3","RF.2.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"chart",std:["2.NBT.A.2"],msg:"The 120 chart shows the counting sequence, so counting and skip-counting done with it is supported, not independent."},{t:"chart",std:["2.OA.C.4"],msg:"With the 120 chart the student can count the pots one square at a time. Note it if the total came from counting by ones instead of from adding the rows."},{t:"pv",std:["2.NBT.B.7"],msg:"The place value chart lines the digits up by place, which is most of the work in a written method. Note it."},{t:"pv",std:["2.NBT.A.2"],msg:"The place value chart sorts the digits into hundreds, tens, and ones for the student, so count those items as supported, not independent."},{t:"blocks",std:["2.NBT.B.7"],msg:"If you built the numbers with blocks for the student, the item shows they can trade with a model, not that they can use a written method on their own."},{t:"chart",std:["2.OA.A.1"],msg:"On the 120 chart a student can hop to the answer instead of adding or subtracting. Note whether the answer came from the chart or from a strategy."},{t:"chart",std:["2.OA.C.3"],msg:"The 120 chart shows the counting numbers, not the pairing. If the odd or even answer came from a remembered pattern of last digits, note that the pairing was not shown."},{t:"pv",std:["2.NBT.A.1","2.NBT.A.3"],msg:"The place value chart sorts the digits into hundreds, tens, and ones for the student, so expanded form and digit meaning read off it are supported, not independent."},{t:"blocks",std:["2.NBT.A.1"],msg:"If you built the number with blocks, the item shows the student can read a model, not that the meaning of each digit is known from the numeral alone."},{t:"coins",std:["2.MD.C.8"],msg:"The coin card gives the name and the value of every coin, which is half of what 2.MD.C.8 asks for. With it open, rate the adding and the subtracting, not the coin knowledge."},{t:"sent",msg:"Sentence starters supply the opening, the linking words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["L.2.2"],msg:"Write It Right checks capitals, marks, and spelling, so the student has to do the writing. If an adult wrote, do not rate L.2.2 from this stop."},{t:"clock",std:["2.MD.C.7","1.MD.B.3"],msg:"The clock card gives the five minute count around the dial and the a.m. and p.m. rule, so a time read with it open is supported, not independent."},{t:"ruler",std:["2.MD.A.1"],msg:"The ruler card names the inch and half inch marks and which tool to pick, so count a measurement made with it open as supported, not independent."},{t:"letters",std:["RF.2.3"],msg:"The letter and sound card lists the patterns, the prefixes and the suffixes with example words, so a word sounded out with it open is supported, not independent."},{t:"retell",std:["RL.2.2","SL.2.4","W.2.3"],msg:"The card gives the beginning, middle, end frame and asks for the lesson, so count the structure as supported and rate the content the student supplies."},{t:"qwords",std:["RL.2.1","RI.2.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.2.4","RF.2.3"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
